import {
  CodeBlock as ChakraCodeBlock,
  Float,
  IconButton,
  type CodeBlockRootProps,
} from "@chakra-ui/react";
import { Check, Clone, Icon } from "./Icon";

type CodeBlockProps = Omit<CodeBlockRootProps, "children"> & {
  code: string;
  /** Sizes token the code area scrolls past, e.g. "96". Grows unbounded when omitted. */
  maxCodeHeight?: string;
};

export const RasaCodeBlock = ({ code, maxCodeHeight, ...props }: CodeBlockProps) => {
  return (
    <ChakraCodeBlock.Root
      code={code}
      fontFamily="mono"
      size="sm"
      defaultColorScheme="light"
      css={maxCodeHeight ? { "--code-block-max-height": `sizes.${maxCodeHeight}` } : undefined}
      {...props}
    >
      <ChakraCodeBlock.Content>
        <Float placement="top-end" offset="5" zIndex="1">
          <ChakraCodeBlock.CopyTrigger asChild>
            <IconButton variant="ghost" size="xs" borderRadius="lg" aria-label="Copy code">
              <ChakraCodeBlock.CopyIndicator copied={<Icon icon={Check} />}>
                <Icon icon={Clone} />
              </ChakraCodeBlock.CopyIndicator>
            </IconButton>
          </ChakraCodeBlock.CopyTrigger>
        </Float>
        <ChakraCodeBlock.Code>
          <ChakraCodeBlock.CodeText />
        </ChakraCodeBlock.Code>
      </ChakraCodeBlock.Content>
    </ChakraCodeBlock.Root>
  );
};
